import onnxruntime as ort
import numpy as np
# Initialize once; TensorRT compiles FP16 computation with a 6 GiB workspace.
if 'session' not in globals():
    model_path = 'models/yolo11s.onnx'
    session = ort.InferenceSession(model_path, providers=[('TensorrtExecutionProvider', {'trt_fp16_enable': True, 'trt_max_workspace_size': 6442450944})])
    if 'TensorrtExecutionProvider' not in session.get_providers():
        raise RuntimeError('TensorRT execution provider is required')
raw = session.run(['output0'], {'images': p03i_blob})[0]
return np.asarray(raw, dtype=np.float32)

def iou(a, b):
    ix1, iy1 = max(a[0], b[0]), max(a[1], b[1])
    ix2, iy2 = min(a[2], b[2]), min(a[3], b[3])
    intersection = max(0.0, ix2 - ix1) * max(0.0, iy2 - iy1)
    area_a = max(0.0, a[2] - a[0]) * max(0.0, a[3] - a[1])
    area_b = max(0.0, b[2] - b[0]) * max(0.0, b[3] - b[1])
    union = area_a + area_b - intersection
    return intersection / union if union > 0 else 0.0

# State persists for this input throughout the full video; IDs never recycle.
if 'tracker_state' not in globals():
    tracker_state = {'next_id': 1, 'objects': {}}
objects = tracker_state['objects']
frame_index = p05i_meta['frame_index']
# Advance missed ages even when the current detection collection is empty.
for state in objects.values():
    state['missed'] += max(1, frame_index - state['last_frame']) if state['missed'] == 0 else 1
pairs = []
for track_id, state in objects.items():
    if state['missed'] > 30:
        continue
    for detection_index, det in enumerate(p05i_detections):
        if state['class'] == det['class']:
            overlap = iou(state['box'], det['box'])
            if overlap >= 0.3:
                pairs.append((overlap, track_id, detection_index))
matched_ids, matched_detections = set(), set()
current = []
for overlap, track_id, detection_index in sorted(pairs, key=lambda p: (-p[0], p[1], p[2])):
    if track_id in matched_ids or detection_index in matched_detections:
        continue
    det = p05i_detections[detection_index]
    objects[track_id] = {'box': det['box'], 'class': det['class'], 'missed': 0, 'last_frame': frame_index}
    matched_ids.add(track_id)
    matched_detections.add(detection_index)
    current.append({'track_id': track_id, 'class': det['class'], 'label': det['label'], 'box': det['box'], 'score': det['score']})
for detection_index, det in enumerate(p05i_detections):
    if detection_index in matched_detections:
        continue
    track_id = tracker_state['next_id']
    tracker_state['next_id'] += 1
    objects[track_id] = {'box': det['box'], 'class': det['class'], 'missed': 0, 'last_frame': frame_index}
    current.append({'track_id': track_id, 'class': det['class'], 'label': det['label'], 'box': det['box'], 'score': det['score']})
for track_id in list(objects):
    if objects[track_id]['missed'] > 30:
        del objects[track_id]
return current  # Only objects observed in this frame, not retained missed IDs.
